void testPow_29_oe() {
    Fraction f = null;

    f = Fraction.of(3, 5);
    // removed other assertion

    f = Fraction.of(3, 5);
    // removed other assertion
    // removed other assertion

    f = Fraction.of(3, 5);
    f = f.pow(2);
    // removed other assertion
    // removed other assertion

    f = Fraction.of(3, 5);
    f = f.pow(3);
    // removed other assertion
    // removed other assertion

    f = Fraction.of(3, 5);
    f = f.pow(-1);
    // removed other assertion
    // removed other assertion

    f = Fraction.of(3, 5);
    f = f.pow(-2);
    // removed other assertion
    // removed other assertion

    // check unreduced fractions stay that way.
    f = Fraction.of(6, 10);
    // removed other assertion

    f = Fraction.of(6, 10);
    // removed other assertion
    // removed other assertion

    f = Fraction.of(6, 10);
    f = f.pow(2);
    // removed other assertion
    // removed other assertion

    f = Fraction.of(6, 10);
    f = f.pow(3);
    // removed other assertion
    // removed other assertion

    f = Fraction.of(6, 10);
    f = f.pow(-1);
    // removed other assertion
    // removed other assertion

    f = Fraction.of(6, 10);
    f = f.pow(-2);
    // removed other assertion
    // removed other assertion

    // zero to any positive power is still zero.
    f = Fraction.of(0, 1231);
    f = f.pow(1);
    // removed other assertion
    // removed other assertion
    // removed other assertion
    f = f.pow(2);
    // removed other assertion
    // removed other assertion
    // removed other assertion

    // zero to negative powers should throw an exception
    final Fraction fr = f;
    assertThrows(ArithmeticException.class, () -> fr.pow(-1));
}

